$ErrorActionPreference = 'Stop'

$outDir = Join-Path $PSScriptRoot 'deliverables'
New-Item -ItemType Directory -Force -Path $outDir | Out-Null

function Esc([string]$s) { if ($null -eq $s) { return '' }; return [System.Security.SecurityElement]::Escape($s) }
function Run([string]$text, [switch]$Bold, [int]$Size = 21, [string]$Color = '222222') {
  $b = if ($Bold) { '<w:b/>' } else { '' }
  return "<w:r><w:rPr>$b<w:color w:val='$Color'/><w:sz w:val='$Size'/><w:szCs w:val='$Size'/><w:rFonts w:ascii='Aptos' w:hAnsi='Aptos' w:eastAsia='Malgun Gothic'/></w:rPr><w:t xml:space='preserve'>$(Esc $text)</w:t></w:r>"
}
function P([string]$text, [string]$style = '', [string]$align = '', [switch]$Bold, [int]$Size = 21, [int]$before = 0, [int]$after = 80) {
  $st = if ($style) { "<w:pStyle w:val='$style'/>" } else { '' }
  $al = if ($align) { "<w:jc w:val='$align'/>" } else { '' }
  return "<w:p><w:pPr>$st$al<w:spacing w:before='$before' w:after='$after'/></w:pPr>$(Run $text -Bold:$Bold -Size $Size)</w:p>"
}
function Cell([string]$text, [int]$width, [switch]$Header) {
  $fill = if ($Header) { "<w:shd w:fill='17365D'/>" } else { '' }
  $color = if ($Header) { 'FFFFFF' } else { '222222' }
  return "<w:tc><w:tcPr><w:tcW w:w='$width' w:type='dxa'/>$fill<w:tcMar><w:top w:w='70' w:type='dxa'/><w:left w:w='80' w:type='dxa'/><w:bottom w:w='70' w:type='dxa'/><w:right w:w='80' w:type='dxa'/></w:tcMar></w:tcPr><w:p><w:pPr><w:spacing w:after='0'/></w:pPr>$(Run $text -Bold:$Header -Size 17 -Color $color)</w:p></w:tc>"
}
function Table([array]$headers, [array]$rows, [array]$widths) {
  $xml = "<w:tbl><w:tblPr><w:tblW w:w='0' w:type='auto'/><w:tblLayout w:type='fixed'/><w:tblBorders><w:top w:val='single' w:sz='4' w:color='9AA7B5'/><w:left w:val='single' w:sz='4' w:color='9AA7B5'/><w:bottom w:val='single' w:sz='4' w:color='9AA7B5'/><w:right w:val='single' w:sz='4' w:color='9AA7B5'/><w:insideH w:val='single' w:sz='4' w:color='CAD2DA'/><w:insideV w:val='single' w:sz='4' w:color='CAD2DA'/></w:tblBorders></w:tblPr><w:tr>"
  for ($i=0; $i -lt $headers.Count; $i++) { $xml += Cell $headers[$i] $widths[$i] -Header }
  $xml += '</w:tr>'
  foreach ($row in $rows) { $xml += '<w:tr>'; for ($i=0; $i -lt $row.Count; $i++) { $xml += Cell ([string]$row[$i]) $widths[$i] }; $xml += '</w:tr>' }
  return $xml + '</w:tbl>'
}
function PageBreak { return '<w:p><w:r><w:br w:type="page"/></w:r></w:p>' }

