  @('EBS / KBS World Korean','Нэмэлт сонсгол, соёл; багш урьдчилан шалгана / 보충 듣기·문화','https://world.kbs.co.kr/service/learning_korean.htm')
) @(2500,4100,3300)

foreach ($lv in $levels) {
  $body += PageBreak
  $body += P ("{0}-Р ТҮВШИН — {1} / {2}급 — {3}" -f $lv.N,$lv.Mn,$lv.N,$lv.Ko) 'Title'
  $body += P ('Түвшний үр дүн / 단계 성취 목표: ' + $lv.Target)
  $body += P ('Гол хэлзүй / 핵심 문법: ' + $lv.Grammar)
  $body += P 'Түвшний төгсгөлд суралцагч / 수료 시 학습자는' 'Heading2'
  $outcomes = switch ($lv.N) {
    1 { @('Удаан, тод өдөр тутмын ярианы гол мэдээллийг танина. / 천천히 명확한 일상 발화의 핵심 정보를 파악한다.','Тэмдэг, богино мессеж уншина. / 표지와 짧은 메시지를 읽는다.','2 минутын энгийн ярианд оролцоно. / 2분간 기초 대화에 참여한다.','60–100 тэмдэгт бичвэр бүтээнэ. / 60–100자 글을 쓴다.') }
    2 { @('Танил нөхцөлийн ярианы дарааллыг ойлгоно. / 익숙한 상황의 대화 흐름을 이해한다.','Зар, заавар, хувийн захидлаас мэдээлэл олно. / 광고·안내·개인 글에서 정보를 찾는다.','Төлөвлөгөө, туршлага, шалтгааныг холбоно. / 계획·경험·이유를 연결해 말한다.','150–250 тэмдэгт уялдаатай бичнэ. / 150–250자 글을 쓴다.') }
    3 { @('Ердийн мэдээ, хичээл, ажлын ярианы гол санааг ойлгоно. / 일상 뉴스·수업·업무 대화의 요지를 파악한다.','Тайлбар, нийтлэлийн бүтэц ба байр суурийг танина. / 설명문·기사의 구조와 관점을 파악한다.','3–5 минутын бүтэцтэй илтгэл тавина. / 3–5분 발표를 한다.','400–600 тэмдэгт тайлбар, санал бичнэ. / 400–600자 설명·의견문을 쓴다.') }
    4 { @('Хэвийн хурдтай хэлэлцүүлгийн гол нотолгоог ялгана. / 자연스러운 토론의 핵심 근거를 구분한다.','Нийгмийн сэдэвт урт эхээс мэдээлэл нэгтгэнэ. / 사회 주제의 긴 글에서 정보를 통합한다.','Санал зөрөлдөөнийг зохистой удирдана. / 의견 차이를 적절히 조정한다.','700–900 тэмдэгт тайлан, нотолгоот бичвэр бичнэ. / 700–900자 보고·논증문을 쓴다.') }
    5 { @('Мэргэжлийн илтгэл, мэдээний өнгө аясыг тайлбарлана. / 전문 발표·뉴스의 태도를 해석한다.','Олон эхийн нотолгоо ба хазайлтыг үнэлнэ. / 복수 자료의 근거와 편향을 평가한다.','7 минутын эх сурвалжтай илтгэл, хэлэлцүүлэг хийнэ. / 근거 기반 7분 발표·토론을 한다.','1200–1500 тэмдэгт аналитик эсээ бичнэ. / 1200–1500자 분석문을 쓴다.') }
    6 { @('Хурдан, далд утгатай мэргэжлийн дискурсыг ойлгоно. / 빠르고 함축적인 전문 담화를 이해한다.','Академик ба бодлогын эхийг шүүмжлэн нийлэгжүүлнэ. / 학술·정책 자료를 비판적으로 종합한다.','Хэл найруулгаа үзэгч, зорилгод нарийн тохируулна. / 청중·목적에 맞게 문체를 정교하게 조절한다.','1800–2500 тэмдэгт судалгааны/бодлогын бичвэр бүтээнэ. / 1800–2500자 연구·정책 글을 쓴다.') }
  }
  foreach ($o in $outcomes) { $body += P ('• ' + $o) '' '' -Size 19 -after 30 }
  $body += P 'Сэдэвчилсэн төлөвлөгөө / 주제별 교육 계획' 'Heading1'
  $rows = @(); $i=0
  foreach ($u in $lv.Units) {
    $i++; $hrs = if ($i -le 14) { '7' } else { '11' }
    $rows += ,@([string]$i,"$($u[1])`n$($u[0])",$u[2],$u[3],$u[4],$u[5],$hrs)
  }
  $body += Table @('№','Сэдэв / 주제','Хэлзүй / 문법','Чадварын зорилт / 기능','Үгс / 어휘','Гүйцэтгэл, бие даалт / 수행·과제','цаг') $rows @(350,1250,1450,1900,1200,2700,450)
  $body += P 'Нэгж бүрийн багшийн төлөвлөлт / 단원별 수업 설계' 'Heading2'
  $body += Table @('Алхам / 단계','Минут/цаг','Заавал хийх ажил / 필수 활동','Нотлох баримт / 산출물') @(
    @('Оролт / 도입','20 мин','Зорилго, өмнөх мэдлэг, нөхцөлт зураг/асуулт','Урьдчилсан хариулт'),
    @('Ойлгох / 입력 이해','60 мин','Богино видео/аудио 2 удаа; гол ба нарийн мэдээлэл','Сонсгол/уншлагын хуудас'),
    @('Хэлний төвлөрөл / 언어 초점','90 мин','Үг, дүрэм, дуудлагыг эхээс илрүүлж, хэлбэр–утга–хэрэглээ','Дасгалын 80%+'),
    @('Удирдамжтай дадлага / 통제 연습','90 мин','Солих, холбох, мэдээлэл нөхөх, диктоглосс','Хосын шалгах хуудас'),
    @('Харилцааны даалгавар / 의사소통 과제','120 мин','Мэдээллийн зөрүү, асуудал шийдэх, дүрд тоглох','Бичлэг/бичвэр'),
    @('4 чадварын нэгтгэл / 기능 통합','60 мин','Унших/сонсох эхээс ярих/бичих бүтээгдэхүүн','Рубриктэй бүтээгдэхүүн'),
    @('Үнэлгээ, засвар / 평가·수정','40 мин','Өөрийн/үе тэнгийн үнэлгээ, багшийн feedback, дахин засвар','Эхний ба зассан хувилбар'),
    @('Бие даалт / 자기주도','100 мин','Видео давталт, үгийн карт, портфолио','LMS/портфолио')
  ) @(1800,950,4700,2100)
}

$body += PageBreak
$body += P 'ДАСГАЛЫН САН / 활동·연습 은행' 'Heading1'
$body += P 'Доорх загварыг нэгж бүрийн үг, дүрэм, видео/эхээр сольж хэрэглэнэ. Хариултын түлхүүр нь хаалт доторх шалгуур буюу багшийн жишиг хариултаар тодорхойлогдоно.'
$body += Table @('№','Дасгал / 활동','Заавар / 지시','Шалгалт / 확인') @(
  @('1','Үг–зураг / 어휘-그림','10 үгийг зураг/тодорхойлолттой тааруул; дараа нь 5 өгүүлбэр зохио.','10 оноо + хэрэглээ 5'),
  @('2','Сонсголын 3 үе / 듣기 3단계','Гарчгийг таа; 1-р сонсолтоор гол санаа; 2-р сонсолтоор 5 баримт; 3-р сонсолтоор хэллэг тэмдэглэ.','Гол санаа 2, баримт 5, хэллэг 3'),
  @('3','Диктоглосс / 딕토글로스','60–120 үгтэй эхийг 2 удаа сонсоод бүлгээр утгыг сэргээн бич.','Агуулга 40%, хэл 30%, хамтын засвар 30%'),
  @('4','Мэдээллийн зөрүү / 정보차','А ба Б өөр хүснэгттэй; эхээ үзүүлэхгүй асууж нөх.','Бүрэн байдал + зорилтот хэллэг'),
  @('5','Алдаа засвар / 오류 수정','10 өгүүлбэрийн хэлбэр, утга, найруулгын алдааг ангилан зас.','Алдааны төрөл + зөв хувилбар + тайлбар'),
  @('6','Уншлагын эвлүүлэг / 직소 읽기','Эхийн хэсгийг бүлэг бүр уншиж, шинэ бүлэгт тайлбарлан бүрэн зураг гарга.','Гол санаа, нотолгоо, үгийн таамаг'),
  @('7','Дүрд тоглолт / 역할극','Нөхцөл, зорилго, саадтай карт ашиглан 2–5 минут ярилц.','Гүйцэтгэл, харилцан үйлдэл, хэл'),
  @('8','Бичгийн мөчлөг / 쓰기 과정','Төлөвлөгөө → эхний хувилбар → peer review → засвар → reflection.','Хоёр хувилбар + засварын тайлбар'),
  @('9','Видео сүүдэрлэлт / 영상 섀도잉','15–30 сек хэсгийг 4 удаа сонсож, бичлэгтэй зэрэгцүүлэн дуурай.','Хэмнэл, авиа, төгсгөлийн өнгө'),
  @('10','Баримт–санал / 사실-의견','Эхээс баримт, тайлбар, санал, таамгийг ялгаж хүснэгтэд оруул.','Ангиллын үндэслэл'),
  @('11','TOPIK хувиргалт / TOPIK 변형','Тухайн нэгжийн эхээр түвшинд тохирсон сонгох/нөхөх/бичих даалгавар зохио.','Даалгаврын тодорхой байдал + түлхүүр'),
  @('12','Can-do reflection','“Би чадна…” 4 мэдэгдлийг 1–4 оноогоор үнэлж, нэг нотолгоо хавсарга.','Нотолгоотой өөрийн үнэлгээ')
) @(450,1700,5000,2300)

$body += P 'Видео хичээлийн ажлын хуудас / 영상 학습지' 'Heading2'
$body += P '1. Үзэхийн өмнө / 시청 전: Гарчиг, зурагт тулгуурлан 3 үг, 2 таамаг бич.  2. Эхний үзэлт / 1차: Хэн–хаана–яагаад гэсэн 3 асуултад хариул.  3. Хоёр дахь үзэлт / 2차: 5 нарийн мэдээлэл, 3 зорилтот хэллэг тэмдэглэ.  4. Хэлний ажил / 언어: Нэг өгүүлбэрийг сүүдэрлэж бичлэг хий.  5. Дараах ажил / 후속: Агуулгыг 3 өгүүлбэрээр хураангуйлж, өөрийн жишээ нэм.  6. Дижитал ёс зүй: линкийг хуулбарлан түгээхээс өмнө лиценз, насны тохироо, хувийн мэдээллийг шалга.'

$body += P 'ШАЛГАЛТЫН БЛЮПРИНТ / 평가 청사진' 'Heading1'
$body += Table @('Түвшин','Сонсгол','Уншлага','Бичлэг','Яриа','Хэлний хэрэглээ') @(
  @('1–2','15 мин, 15 даалгавар','20 мин, 15 даалгавар','2 богино бичвэр','Хос яриа + ганцаарчилсан','20 даалгавар'),
  @('3–4','25 мин, 20 даалгавар','35 мин, 20 даалгавар','Хураангуй + нотолгоот бичвэр','Илтгэл + харилцан яриа','Эхэд суурилсан 20 даалгавар'),
  @('5–6','35 мин, 20 даалгавар','50 мин, 20 даалгавар','Нийлэгжүүлэлт + аналитик эсээ','Илтгэл/мэтгэлцээн + Q&A','Редактор, найруулгын 15 даалгавар')
) @(1000,1700,1700,1800,1800,1800)
$body += P 'Шалгалтын чанарын шаардлага / 시험 품질 기준' 'Heading2'
foreach ($x in @('Хичээлээр үзээгүй хэлбэрийг өндөр жинтэйгээр шалгахгүй. / 미학습 요소를 고비중으로 평가하지 않는다.','Даалгавар бүр зорилтот үр дүн, түвшин, оноо, зөв хариу/рубриктэй байна. / 모든 문항에 성취기준·난이도·배점·정답/루브릭을 명시한다.','Хоёр багш хөндлөн шалгах эсвэл 20%-д давхар үнэлгээ хийж, зөрүү 10%-иас их бол тохируулна. / 20% 이중 채점, 10% 이상 차이는 조정한다.','Тусгай хэрэгцээнд нэмэлт хугацаа, том фонт, тусдаа орчин зэрэг үндэслэлтэй тохируулга хийнэ. / 합리적 평가 편의를 제공한다.')) { $body += P ('• ' + $x) '' '' -Size 19 -after 25 }

$body += P 'БАГШИЙН БАРИМТ БИЧИГ / 교사용 운영 서식' 'Heading1'
$body += Table @('Маягт / 서식','Заавал бүртгэх зүйл / 필수 기록') @(
  @('Нэгжийн төлөвлөгөө / 단원 계획','Үр дүн, эх, зорилтот хэл, үе шат, ялгаатай дэмжлэг, үнэлгээ, гэрийн ажил'),
  @('Ирц ба оролцоо / 출결·참여','Огноо, ирц, хоцролт, нөхөх ажил, суралцагчийн холбоо'),
  @('Үнэлгээ / 성적','Даалгавар, шалгуур, оноо, feedback, дахин гүйцэтгэл'),
  @('Портфолио / 포트폴리오','Эхний/зассан хувилбар, аудио/видео зөвшөөрөл, өөрийн үнэлгээ'),
  @('Материалын бүртгэл / 자료 기록','Гарчиг, URL, нэвтэрсэн огноо, лиценз, түвшин, хадмал, хүртээмж'),
  @('Ахицын уулзалт / 상담','Can-do нотолгоо, хүндрэл, 4 долоо хоногийн зорилго, дэмжлэг')
) @(2700,6700)

$body += P 'ЧАНАРЫН БАТАЛГАА / 품질 보증' 'Heading1'
$body += P 'Улирал эхлэхээс 2 долоо хоногийн өмнө: түвшин тогтоох; материалын линк, лиценз, хадмал шалгах; шалгалтын blueprint батлах. 5 ба 10-р долоо хоногт: ирц, гүйцэтгэл, сэтгэл ханамжид тулгуурласан эрт дэмжлэг. Улирлын дараа: даалгаврын хүндрэл/ялгах чадвар, рубрикийн найдвартай байдал, суралцагчийн санал, багшийн эргэцүүллийг хянаж хөтөлбөрийн өөрчлөлтийг хувилбараар бүртгэнэ.'
$body += P '개강 2주 전 배치평가·자료 링크/저작권·평가 청사진을 점검한다. 5주·10주차에는 출결·성취·만족도 자료로 조기 지원한다. 종강 후 문항 난이도·변별도, 채점 신뢰도, 학습자 의견, 교사 성찰을 검토하고 교육과정 변경 이력을 관리한다.'

$body += P 'ЭХ СУРВАЛЖ / 참고 자료' 'Heading1'
$body += P '1. 세종학당재단, 교육과정 개발·운영: https://www.ksif.or.kr/com/cmm/EgovContentView.do?menuNo=20102100'
$body += P '2. 세종학당재단, 한국어·한국문화 교육자료: https://www.ksif.or.kr/com/cmm/EgovContentView.do?menuNo=20102200'
