 <w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:spacing w:before="260" w:after="100"/><w:keepNext/></w:pPr><w:rPr><w:b/><w:color w:val="17365D"/><w:sz w:val="28"/></w:rPr></w:style>
 <w:style w:type="paragraph" w:styleId="Heading2"><w:name w:val="heading 2"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:spacing w:before="180" w:after="80"/><w:keepNext/></w:pPr><w:rPr><w:b/><w:color w:val="2F5597"/><w:sz w:val="24"/></w:rPr></w:style>
</w:styles>
"@
$contentTypes = @"
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/><Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/></Types>
"@
$rels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/></Relationships>'
$docRels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>'
$core = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>JIM Global Солонгос хэлний 1–6 түвшний хөтөлбөр</dc:title><dc:creator>JIM Global</dc:creator><dc:subject>한국어 1–6급 통합 교육과정</dc:subject><dcterms:created xsi:type="dcterms:W3CDTF">2026-08-28T00:00:00Z</dcterms:created></cp:coreProperties>'
$app = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes"><Application>Microsoft Office Word</Application><Company>JIM Global</Company></Properties>'

$tmp = Join-Path ([System.IO.Path]::GetTempPath()) ('jim_curriculum_' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $tmp | Out-Null
New-Item -ItemType Directory -Path (Join-Path $tmp '_rels'),(Join-Path $tmp 'word'),(Join-Path $tmp 'word\_rels'),(Join-Path $tmp 'docProps') | Out-Null
[IO.File]::WriteAllText((Join-Path $tmp '[Content_Types].xml'),$contentTypes,[Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText((Join-Path $tmp '_rels\.rels'),$rels,[Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText((Join-Path $tmp 'word\document.xml'),$docXml,[Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText((Join-Path $tmp 'word\styles.xml'),$styles,[Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText((Join-Path $tmp 'word\_rels\document.xml.rels'),$docRels,[Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText((Join-Path $tmp 'docProps\core.xml'),$core,[Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText((Join-Path $tmp 'docProps\app.xml'),$app,[Text.UTF8Encoding]::new($false))
Add-Type -AssemblyName System.IO.Compression.FileSystem
$docx = Join-Path $outDir 'JIM_Global_Korean_Curriculum_Level_1-6_MN-KO.docx'
if (Test-Path $docx) { Remove-Item -LiteralPath $docx }
[IO.Compression.ZipFile]::CreateFromDirectory($tmp,$docx)
Remove-Item -LiteralPath $tmp -Recurse -Force

$pdf = Join-Path $outDir 'JIM_Global_Korean_Curriculum_Level_1-6_MN-KO.pdf'
try {
  $word = New-Object -ComObject Word.Application
  $word.Visible = $false
  $d = $word.Documents.Open($docx)
  $d.Fields.Update() | Out-Null
  $d.ExportAsFixedFormat($pdf,17)
  $pages = $d.ComputeStatistics(2)
  $d.Close($false); $word.Quit()
  [Runtime.InteropServices.Marshal]::ReleaseComObject($d) | Out-Null
  [Runtime.InteropServices.Marshal]::ReleaseComObject($word) | Out-Null
  Write-Output "DOCX=$docx`nPDF=$pdf`nPAGES=$pages"
} catch {
  if ($d) { $d.Close($false) }; if ($word) { $word.Quit() }
  Write-Output "DOCX=$docx`nPDF conversion unavailable: $($_.Exception.Message)"
}
